<?php
namespace App\Modules\Production\Domain\Models;
use App\Modules\Catalog\Domain\Models\Item; use App\Modules\Catalog\Domain\Models\ProductPresentation; use App\Modules\Catalog\Domain\Models\Unit; use App\Modules\Recipes\Domain\Models\ProductFinishingComponent; use App\Modules\Recipes\Domain\Models\RecipeIngredient; use Illuminate\Database\Eloquent\Attributes\Fillable; use Illuminate\Database\Eloquent\Concerns\HasUlids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
#[Fillable(['production_order_id','recipe_ingredient_id','finishing_component_id','item_id','presentation_id','calculated_quantity','actual_quantity','unit_id','unit_cost','total_cost','difference_reason'])]
class ProductionConsumption extends Model { use HasUlids; public function order():BelongsTo{return $this->belongsTo(ProductionOrder::class,'production_order_id');} public function recipeIngredient():BelongsTo{return $this->belongsTo(RecipeIngredient::class);} public function finishingComponent():BelongsTo{return $this->belongsTo(ProductFinishingComponent::class);} public function item():BelongsTo{return $this->belongsTo(Item::class);} public function presentation():BelongsTo{return $this->belongsTo(ProductPresentation::class);} public function unit():BelongsTo{return $this->belongsTo(Unit::class);} protected function casts():array{return ['calculated_quantity'=>'decimal:6','actual_quantity'=>'decimal:6','unit_cost'=>'integer','total_cost'=>'integer'];} }
